// Reads recent error executions and decides per execution:
//   'retry'  -> attempts left
//   'giveup' -> exhausted, alert once
// Attempt counts are tracked in workflow static data and chained across retries.

const cfg = $('Config').first().json;
const MAX_RETRIES = cfg.MAX_RETRIES ?? 3;

const body = $input.first().json;
const executions = Array.isArray(body.data) ? body.data : [];

const staticData = $getWorkflowStaticData('global');
if (!staticData.attempts) staticData.attempts = {}; // execId -> number
if (!staticData.done) staticData.done = {};         // execId -> true

const out = [];

for (const exec of executions) {
  const execId = String(exec.id);

  // Already fully handled (retried or given up) -> skip
  if (staticData.done[execId]) continue;

  const attempts = staticData.attempts[execId] ?? 0;
  const workflowId = exec.workflowId ?? exec.workflowData?.id ?? '';
  const workflowName = exec.workflowData?.name ?? 'Unknown workflow';

  if (attempts < MAX_RETRIES) {
    // Mark this execution as handled so we don't pick it again next run.
    staticData.done[execId] = true;
    out.push({
      json: { action: 'retry', executionId: execId, workflowId, workflowName, attempts },
    });
  } else {
    staticData.done[execId] = true;
    out.push({
      json: { action: 'giveup', executionId: execId, workflowId, workflowName, attempts },
    });
  }
}

return out;

// The retry created a new execution. Carry the attempt count forward so the
// chain is bounded by MAX_RETRIES rather than restarting at 0 each time.
const staticData = $getWorkflowStaticData('global');
if (!staticData.attempts) staticData.attempts = {};

for (const item of $input.all()) {
  const prev = $('Decide Actions').itemMatching(item.pairedItem?.item ?? 0)?.json ?? {};
  const newExec = item.json;
  const newId = String(newExec.id ?? '');
  const prevAttempts = prev.attempts ?? 0;
  if (newId) {
    staticData.attempts[newId] = prevAttempts + 1;
  }
}

return $input.all();

